use strict;
use warnings;

my $s = "42";
print $s + 8, "\n";
print $s . 8, "\n";
my $f = "3.14";
printf "%.2f\n", $f * 2;
my $n = 10;
print "length of the number 10: ", length($n), "\n";
my $v = "007";
print $v + 0, "\n";
print "$v\n";
print(($v == 7)   ? "numeric equal\n"   : "numeric differ\n");
print(($v eq "7") ? "string equal\n"    : "string differ\n");
my $big = 1_000_000;
print "$big\n";
my $hex = 0xff;
my $oct = 0755;
my $bin = 0b1010;
print "$hex $oct $bin\n";
print hex("ff"), " ", oct("0755"), " ", oct("0x1f"), "\n";
my $sci = 1.5e3;
print "$sci\n";
my $mixed = "5";
$mixed++;
print "after ++: $mixed\n";
my $concat = 1 . 2;
print "1 . 2 = $concat and it is ", ($concat + 1), " when used as a number\n";
